select.where:
del_flag='0'
and sap = #{sap}
 and INSTR(spec_desc, #{specDesc}) > 0
and embryo_code = #{embryoCode}
and line_type = #{lineType}
and job_type = #{jobType}

mapper.update:
update t_specify_machine
project_desc = #{projectDesc}, sap = #{sap}, spec_desc = #{specDesc}, embryo_code = #{embryoCode}, line_type = #{lineType}, job_type = #{jobType}, create_by = #{createBy}, create_time = #{createTime}, update_by = #{updateBy}, update_time = #{updateTime}, del_flag = #{delFlag}, remark = #{remark},
where id = #{id}

mapper.insert:
insert into t_specify_machine_list (ID, SPECIFY_MACHINE_ID, PROCEDURE_CODE, MACHINE_ID, MACHINE_CODE, CREATE_BY, CREATE_TIME, UPDATE_BY, UPDATE_TIME, DEL_FLAG, REMARK) select seq_t_specify_machine_list.nextval, A.* from(
SELECT #{item.specifyMachineId,jdbcType=DECIMAL}, #{item.procedureCode,jdbcType=VARCHAR}, #{item.machineId,jdbcType=VARCHAR}, #{item.machineCode,jdbcType=VARCHAR}, #{item.createBy,jdbcType=VARCHAR}, #{item.createTime,jdbcType=DATE}, #{item.updateBy,jdbcType=VARCHAR}, #{item.updateTime,jdbcType=DATE}, #{item.delFlag,jdbcType=CHAR}, #{item.remark,jdbcType=VARCHAR} from dual
) A

select.where:
del_flag='0'
and id != #{id}
and embryo_code = #{embryoCode}
and sap is null
and sap = #{sap}
